class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount): ...

class Card(PaymentStrategy):
    def pay(self, amount):
        return f"card {amount}"

class PayPal(PaymentStrategy):
    def pay(self, amount):
        return f"paypal {amount}"

